import "./App.css";
import { useState } from "react";
function App() {
  const { billAmount, setBillAmount } = useState(0);
  const { yourTipPercentage, setYourTipPercentage } = useState(0);
  const { friendsTipPercentage, setFriendsTipPercentage } = useState(0);

  return (
    <div>
      <BillCost billAmount={billAmount} setBillAmount={setBillAmount} />
      <howDoYouLikeService
        yourTipPercentage={yourTipPercentage}
        setYourTipPercentage={setYourTipPercentage}
      />
      <howDoYourFriendsLikeService
        friendsTipPercentage={friendsTipPercentage}
        setFriendsTipPercentage={setFriendsTipPercentage}
      />
      <calculateBill
        billAmount={billAmount}
        yourTipPercentage={yourTipPercentage}
        friendsTipPercentage={friendsTipPercentage}
      />
    </div>
  );
}

function BillCost({ billAmount, setBillAmount }) {
  return (
    <div>
      <label htmlFor="bill">Enter the bill amount:</label>
      <input
        type="number"
        id="bill"
        value={billAmount}
        onChange={(e) => setBillAmount(parseFloat(e.target.value) || 0)}
      />
    </div>
  );
}

function howDoYouLikeService({ yourTipPercentage, setYourTipPercentage }) {
  return (
    <div>
      <label htmlFor="tip">How do you like the service?</label>
      <select
        id="tip"
        value={yourTipPercentage}
        onChange={(e) => setYourTipPercentage(parseInt(e.target.value) || 0)}
      >
        <option value="0">Dissatisfied (0%)</option>
        <option value="5">It was okay (5%)</option>
        <option value="10">It was good (10%)</option>
        <option value="15">absolutely amazing! (15%)</option>
      </select>
    </div>
  );
}

function howDoYourFriendsLikeService({
  friendsTipPercentage,
  setFriendsTipPercentage,
}) {
  return (
    <div>
      <label htmlFor="tip">How do your friends like the service?</label>
      <select
        id="tip"
        value={friendsTipPercentage}
        onChange={(e) => setFriendsTipPercentage(parseInt(e.target.value) || 0)}
      >
        <option value="0">Dissatisfied (0%)</option>
        <option value="5">It was okay (5%)</option>
        <option value="10">It was good (10%)</option>
        <option value="15">absolutely amazing! (15%)</option>
      </select>
    </div>
  );
}

function calculateBill(billAmount, yourTipPercentage, friendsTipPercentage) {
  const tipAmount =
    ((yourTipPercentage + friendsTipPercentage) * billAmount) / 200;
  const totalBill = billAmount * tipAmount;
  return (
    <h1>
      Total Bill is $${totalBill.toFixed(2)} (${billAmount} + $
      {tipAmount.toFixed(2)})
    </h1>
  );
}

export default App;
